<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageRetriesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageRetriesAccessor trait.
 *
 * Covers null default, string/VO assignment via withRetries,
 * getRetries/retries accessors, and isRetriesChanged with/without original.
 */
class MessageRetriesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRetries creates a new instance with the Retries set
     * from a string value, and getRetries returns the primitive string.
     */
    public function testWithRetriesFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageRetriesAccessorUnitTest();

        // Act
        $result = $holder->withRetries(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getRetries());
    }
    /**
     * Asserts that withretries has access to the value object
     * from a string value, and getRetries returns the primitive string.
     */
    public function testWithRetriesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageRetriesAccessorUnitTest();

        // Act
        $result = $holder->withRetries(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->retries()->value());
    }
    public function testChangedRetries(): void
    {
        // Arrange
        $holder = new ImplWithMessageRetriesAccessorUnitTest()->withRetries(1);
        $original = $holder->withRetries( 1);
        $same = $holder->withRetries( 1);
        $modified = $holder->withRetries(2);

        // Act
        $withSame = $original->isRetriesChanged( $same );
        $withDiferent = $original->isRetriesChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageRetriesAccessorUnitTest
{
  use MessageRetriesAccessor;
}
